-- ============================================================
-- Quiz coverage for databases/redis and databases/elasticsearch
-- (overview, fundamentals, intermediate, advanced -- all four
-- tabs exist and carry substantive live content for both).
-- Phase 4 (Databases academy), batch 6 (final): Redis & Elasticsearch.
-- ============================================================

INSERT INTO quiz_questions (academy_slug, technology_slug, section_slug, question, options, correct_index, explanation, difficulty) VALUES

-- ---------- databases/redis/overview ----------
('databases', 'redis', 'overview', 'Why is Redis dramatically faster than a disk-based database for typical read/write operations?', '["Redis uses a more efficient disk format than other databases", "Redis stores data in RAM rather than on disk, and RAM access is orders of magnitude faster than disk I/O -- this is the fundamental reason for its speed, not a specific optimization technique", "Redis compresses all data before storing it", "Redis only supports very small datasets, which makes it artificially fast"]', 1, 'In-memory storage is the foundational reason for Redis''s speed -- everything else (data structures, single-threaded design) builds on top of that core characteristic.', 'beginner'),
('databases', 'redis', 'overview', 'What is the correct, safe command pattern for using Redis as a distributed lock, and why does it matter?', '["SETNX lock:resource 1, with a separate EXPIRE call afterward", "SET lock:resource value NX PX milliseconds -- setting the key, the not-exists condition, and the expiry all atomically in one command, since a crashed lock holder before a separate EXPIRE call would otherwise leave the lock held forever", "GET lock:resource followed by a manual check in application code", "DEL lock:resource before attempting to acquire it"]', 1, 'The atomic SET...NX...PX form avoids the race condition/crash-window risk of doing SETNX and EXPIRE as two separate commands, where a crash between them leaves a lock that can never be released.', 'intermediate'),
('databases', 'redis', 'overview', 'What does TTL command return when a key has no expiry set at all, versus when the key doesn''t exist?', '["Both cases return the same value, making them indistinguishable", "TTL returns -1 when a key exists but has no expiry set, and -2 when the key doesn''t exist at all -- these are two genuinely distinct, distinguishable states", "TTL always returns 0 for both cases", "TTL throws an error if the key doesn''t exist"]', 1, 'Knowing this distinction matters practically -- confusing \"no expiry\" with \"key is gone\" would lead to incorrect assumptions about cache state.', 'beginner'),
('databases', 'redis', 'overview', 'Why is SCAN generally preferred over KEYS pattern for finding keys matching a pattern in a production Redis instance?', '["SCAN and KEYS return different, incompatible result formats", "KEYS blocks the single-threaded Redis server while it scans the entire keyspace, which can cause noticeable latency spikes for all other clients on a large dataset -- SCAN iterates incrementally without blocking, at the cost of needing multiple round trips", "KEYS is deprecated and no longer functions in current Redis versions", "SCAN is only usable within a Lua script, not from a regular client"]', 1, 'This is a foundational Redis operational rule -- KEYS is fine for ad hoc debugging on a small dataset but a genuine production risk on any dataset large enough that scanning it blocks other clients noticeably.', 'beginner'),
('databases', 'redis', 'overview', 'What is the practical use case for a Sorted Set beyond a leaderboard example?', '["Sorted Sets can only be used for gaming leaderboards and nothing else", "Any scenario needing ranked or range-queryable ordering by a numeric score -- rate-limiting windows (score = timestamp), priority queues, or time-series-style range queries (ZRANGEBYSCORE) are all real Sorted Set use cases beyond leaderboards specifically", "Sorted Sets are functionally identical to regular Sets with no additional capability", "Sorted Sets cannot have their scores updated after insertion"]', 1, 'Recognizing Sorted Sets as a general \"ranked/range-queryable data\" tool -- not just a leaderboard-specific structure -- is useful for spotting when they''re the right choice for other problems.', 'intermediate'),

-- ---------- databases/redis/fundamentals ----------
('databases', 'redis', 'fundamentals', 'What is the cache-aside (lazy loading) pattern, and what happens on a cache miss?', '["The application always writes to both the cache and database on every request", "On a read, the application checks the cache first; on a miss, it queries the database, then writes the result into the cache for future reads -- the cache is populated lazily, only as data is actually requested", "Cache-aside means the cache is updated automatically whenever the database changes, with no application code involved", "Cache-aside requires the cache and database to always be perfectly synchronized at all times"]', 1, 'This lazy-population behavior is the defining characteristic of cache-aside -- it''s reactive to actual read requests rather than proactively mirroring the database.', 'beginner'),
('databases', 'redis', 'fundamentals', 'Why is a fixed-window rate limiter (INCR + EXPIRE keyed by a time bucket) not the same as a true sliding-window rate limiter, even though both are sometimes casually called "sliding window"?', '["They are functionally identical in every scenario", "A fixed window resets entirely at each window boundary, which can allow a burst of up to 2x the limit right at the boundary (e.g. a full limit at the end of one window plus a full limit at the start of the next) -- a true sliding window (sorted-set or Lua-based) tracks a continuously moving time range instead, avoiding this boundary-burst behavior", "A sliding window is always slower and less accurate than a fixed window", "Fixed-window rate limiters cannot use Redis at all"]', 1, 'This distinction matters because mislabeling a fixed-window implementation as \"sliding window\" is a common inaccuracy -- knowing the actual behavioral difference at window boundaries is the real test of understanding.', 'intermediate'),
('databases', 'redis', 'fundamentals', 'Why does the WATCH command paired with MULTI/EXEC provide optimistic locking rather than a blocking lock?', '["WATCH physically blocks other clients from modifying the watched key", "WATCH monitors a key for changes; if the key is modified by another client between WATCH and EXEC, the transaction fails (aborts) rather than executing with stale assumptions -- the client then typically retries, rather than ever having blocked another client''s access to the key", "WATCH and MULTI/EXEC together guarantee the transaction always succeeds eventually with no retry needed", "WATCH is only usable with String keys, not other data structures"]', 1, 'This is a genuine optimistic concurrency control pattern -- no one is blocked from accessing the key, but a conflicting change causes the dependent transaction to abort and retry rather than silently overwriting based on stale data.', 'intermediate'),
('databases', 'redis', 'fundamentals', 'What does `maxmemory-policy allkeys-lru` actually do, and when is it the wrong choice?', '["It evicts the most recently used keys first, regardless of TTL", "It evicts the least recently used keys (regardless of whether they have a TTL) once maxmemory is reached -- this is a good default for a pure cache, but the wrong choice for a Redis instance being used as a durable data store, where noeviction (returning an error instead of silently deleting data) is more appropriate", "allkeys-lru only applies to keys with an expiry set", "This policy prevents Redis from ever running out of memory"]', 1, 'Choosing an eviction policy is a real design decision tied to what Redis is actually being used for -- a durable-data-store use case needs a fundamentally different policy than a pure-cache use case.', 'intermediate'),
('databases', 'redis', 'fundamentals', 'What guarantee does Redis Pub/Sub NOT provide, which is exactly why Redis Streams exist as an alternative?', '["Pub/Sub cannot deliver messages to more than one subscriber at once", "Pub/Sub provides no persistence or delivery guarantee -- a subscriber that is offline or disconnected when a message is published simply never receives it; Streams provide durable, consumer-group-based delivery with acknowledgment, addressing exactly this gap", "Pub/Sub messages are always delivered even if no subscriber is currently listening", "Pub/Sub and Streams provide identical guarantees and differ only in syntax"]', 1, 'This durability gap is the core reason Streams exist as a distinct feature -- recognizing when Pub/Sub''s fire-and-forget behavior is insufficient for a given requirement is a real design decision.', 'intermediate'),

-- ---------- databases/redis/intermediate ----------
('databases', 'redis', 'intermediate', 'What is the actual performance benefit of pipelining multiple Redis commands, and what does it NOT provide?', '["Pipelining makes each individual command execute faster on the server", "Pipelining batches multiple commands into a single network round trip instead of one round trip per command, which is the actual source of the speedup -- it does NOT provide atomicity across the batched commands (that requires MULTI/EXEC transactions instead)", "Pipelining automatically makes all batched commands execute as one atomic transaction", "Pipelining only works with read commands, never write commands"]', 1, 'Conflating pipelining (a network-efficiency optimization) with transactions (an atomicity guarantee) is a common confusion -- they solve genuinely different problems and can be combined but aren''t the same thing.', 'intermediate'),
('databases', 'redis', 'intermediate', 'Why does a Lua script executed via EVAL run atomically with respect to other Redis commands?', '["Lua scripts are executed on a separate thread from the main Redis event loop", "Redis executes the entire Lua script as a single operation on its single-threaded event loop -- no other client command can be interleaved between the script''s individual steps, which is exactly what makes Lua scripts useful for atomic check-and-act patterns like rate limiting", "EVAL commands are queued and executed only during Redis's idle periods", "Atomicity is only guaranteed if the script contains fewer than 10 Redis commands"]', 1, 'This atomicity guarantee follows directly from Redis''s single-threaded command execution model -- it''s the same underlying property that makes Lua scripting a reliable tool for atomic multi-step logic.', 'advanced'),
('databases', 'redis', 'intermediate', 'In Redis Streams, what is the purpose of a consumer group, and what does XACK accomplish?', '["Consumer groups exist purely for access control, unrelated to message processing", "A consumer group lets multiple workers share the workload of processing a stream, with each message delivered to only one consumer in the group; XACK marks a specific message as successfully processed, removing it from the Pending Entries List (PEL) -- messages not acknowledged remain pending and can be reclaimed/redelivered", "XACK deletes the message from the stream entirely, unlike regular consumption", "Consumer groups automatically retry failed messages without any application code involved"]', 1, 'The PEL and explicit acknowledgment (XACK) are what make Streams durable and reliable for multi-worker processing -- a crashed worker''s unacknowledged messages remain recoverable, unlike Pub/Sub''s fire-and-forget model.', 'advanced'),
('databases', 'redis', 'intermediate', 'Why might a rate-limiting Lua script call EXPIRE only when the counter is first created (`if current == 0 then ... EXPIRE`), rather than on every increment?', '["EXPIRE can only be called once per key for the lifetime of that key", "Calling EXPIRE only on the first increment sets the window''s expiry once, tied to when the window actually started -- calling it on every increment would continuously push back the expiry as long as requests keep arriving, effectively preventing the window from ever resetting under sustained traffic", "This is purely a performance optimization with no correctness implication", "EXPIRE has no effect the second time it''s called on the same key regardless of timing"]', 1, 'This is a genuinely subtle correctness detail in fixed-window rate limiter implementations -- resetting the TTL on every request breaks the intended fixed-window semantics by perpetually extending the window.', 'advanced'),
('databases', 'redis', 'intermediate', 'What real problem does the GET_RANK_SCRIPT pattern (a Lua script combining ZSCORE, ZREVRANK, and ZCARD in one call) solve compared to calling those three commands separately from application code?', '["It solves a security vulnerability present in calling the commands individually", "It guarantees the three related pieces of data (a player''s score, rank, and total player count) reflect a single, consistent point in time -- calling them as three separate round trips risks the underlying sorted set changing between calls, producing inconsistent results", "Separate commands cannot be run against a Sorted Set at all", "This pattern only works if the Sorted Set has fewer than 1000 members"]', 1, 'Bundling related reads into one atomic Lua script is a genuine consistency technique -- it avoids the subtle bug where concurrent writes between separate round trips could produce a rank/score/total that don''t actually correspond to the same moment.', 'advanced'),

-- ---------- databases/redis/advanced ----------
('databases', 'redis', 'advanced', 'What problem do hash tags (e.g. `{user:123}:session`) solve in Redis Cluster?', '["Hash tags are purely cosmetic and have no functional effect on clustering", "Redis Cluster distributes keys across shards based on a hash of the key -- hash tags force multiple related keys to hash to the same slot (and therefore the same shard) by hashing only the portion inside {}, which is necessary for multi-key operations like MGET, pipelining, or transactions that require all involved keys to be on the same shard", "Hash tags disable sharding entirely for tagged keys", "Hash tags are required on every key in a clustered Redis deployment"]', 1, 'Without hash tags, related keys for the same logical entity (like a user''s session, preferences, and cart) could land on different shards, breaking any operation that needs to touch them together atomically or in one round trip.', 'advanced'),
('databases', 'redis', 'advanced', 'Why should specific throughput-multiplier claims for Redis alternatives like KeyDB or Dragonfly (e.g. "5-10x" or "25x faster") be treated cautiously?', '["These claims are always accurate regardless of workload", "These are vendor-published benchmark figures that are highly workload- and hardware-dependent -- the actual speedup for any specific application depends on factors like command mix, concurrency level, and hardware, so a published multiplier shouldn''t be assumed to transfer directly to a different workload without independent verification", "Multi-threaded Redis forks never actually outperform single-threaded Redis in practice", "These specific numbers are guaranteed by the vendors under a service level agreement"]', 1, 'Treating vendor benchmark numbers as universal truths rather than workload-specific data points is a common but avoidable mistake when evaluating infrastructure alternatives.', 'advanced'),
('databases', 'redis', 'advanced', 'What does mem_fragmentation_ratio below 1.0 indicate, as opposed to above 1.5?', '["Both ranges indicate the exact same underlying problem", "A ratio above 1.5 indicates memory fragmentation (allocated-but-unused memory not returned to the OS); a ratio below 1.0 is actually a different, also concerning problem -- it suggests memory has been swapped to disk, since Redis''s process RSS is lower than its logical used_memory would suggest", "mem_fragmentation_ratio only matters when using the RDB persistence mode", "A ratio below 1.0 is always harmless and requires no investigation"]', 1, 'Both directions of this ratio being away from ~1.0 are diagnostic signals worth understanding distinctly -- high fragmentation and swapping are different problems with different fixes.', 'advanced'),
('databases', 'redis', 'advanced', 'Why is enabling BOTH RDB and AOF persistence commonly recommended for production Redis, rather than choosing just one?', '["Using both is required by Redis and cannot be disabled", "RDB provides fast restart via compact point-in-time snapshots (but with potential data loss between snapshots), while AOF provides near-zero data loss by logging every write (but with larger files and slower restart) -- enabling both combines RDB''s fast-restart benefit with AOF''s durability, covering each other''s individual weakness", "AOF alone provides no durability benefit over RDB alone", "RDB and AOF cannot both be enabled simultaneously on the same Redis instance"]', 1, 'This complementary tradeoff (fast restart vs. minimal data loss) is exactly why \"use both\" is the standard production recommendation rather than picking one persistence mechanism exclusively.', 'intermediate'),
('databases', 'redis', 'advanced', 'Why does Redis Sentinel require a minimum of 3 Sentinel processes with quorum-based decision making, rather than just 1?', '["A single Sentinel process would be more reliable than multiple ones", "Quorum-based agreement across multiple Sentinels (typically 2 of 3) prevents a single Sentinel''s own failure or network partition from triggering an incorrect failover decision -- this mirrors the same majority-vote reasoning used in other quorum-based distributed systems to avoid a single point of failure making unilateral, potentially wrong decisions", "3 Sentinels are required purely for load-balancing read queries, unrelated to failover", "Sentinel quorum size has no relationship to failover safety"]', 1, 'This is the same general quorum/majority-vote principle that shows up across distributed systems generally (not unique to Redis) -- requiring agreement among multiple independent observers avoids a single faulty node causing an incorrect action.', 'advanced'),

-- ---------- databases/elasticsearch/overview ----------
('databases', 'elasticsearch', 'overview', 'What is the fundamental unit that makes up an Elasticsearch index, and what is each one built on?', '["A row, directly equivalent to a relational database row", "A shard -- each shard is itself a self-contained Lucene index, and an Elasticsearch index is distributed across multiple shards", "A node, with one node per index required", "A cluster, with each index requiring its own dedicated cluster"]', 1, 'Understanding that a shard is a real, self-contained Lucene index (not just an abstract partition) is foundational to reasoning about Elasticsearch''s distribution and scaling model.', 'beginner'),
('databases', 'elasticsearch', 'overview', 'What is the practical difference between a primary shard and a replica shard?', '["They are functionally identical and interchangeable at all times", "A primary shard is set at index creation and cannot be changed without reindexing; a replica shard is a copy of a primary used for high availability and read scaling -- if a primary fails, the cluster can promote a replica to take its place", "Replica shards can be added or removed after creation, but primary shard COUNT also can be changed freely without reindexing", "Only primary shards can be queried; replica shards exist purely for backup and cannot serve reads"]', 1, 'The distinction between fixed-at-creation primary shard count and flexible replica count is a foundational Elasticsearch architecture fact with real operational implications.', 'beginner'),
('databases', 'elasticsearch', 'overview', 'Why is Elasticsearch generally NOT recommended as a primary transactional data store?', '["Elasticsearch cannot store JSON documents at all", "Elasticsearch has limited ACID transaction support and is optimized for search/analytics rather than being the authoritative source of truth -- the standard pattern is a primary database holding authoritative data, with relevant data synced into Elasticsearch specifically to power search features", "Elasticsearch can only store data temporarily, with automatic deletion after 24 hours", "Elasticsearch requires a relational database to function at all"]', 1, 'This is a foundational architectural guideline -- losing an Elasticsearch index should ideally mean \"search is degraded\" (rebuildable from the primary source), not \"data is permanently lost.\"', 'beginner'),
('databases', 'elasticsearch', 'overview', 'What is the current state of Elasticsearch''s licensing, as opposed to the older "dual license from 7.11+" framing?', '["Elasticsearch has always been under a single, unchanged Apache 2.0 license", "As of a 2024 licensing change, Elastic added AGPLv3 (an OSI-approved open source license) as a third option alongside SSPL and Elastic License 2.0 -- making it a genuine three-way choice, and meaning Elasticsearch/Kibana are open source again, not the older two-way \"dual license\" framing from 2021-2024", "OpenSearch and Elasticsearch merged back into a single project in 2024", "Elasticsearch became fully proprietary and closed-source in 2024"]', 1, 'This licensing history (Apache 2.0 -> SSPL/Elastic License in 2021, prompting the OpenSearch fork -> adding AGPLv3 in 2024) is exactly the kind of detail worth getting precisely right rather than relying on outdated framing.', 'intermediate'),
('databases', 'elasticsearch', 'overview', 'What does a dense_vector field type with a "knn" query enable that a standard text/keyword field cannot?', '["dense_vector fields can only store integers, never floating-point numbers", "dense_vector fields store embeddings (numeric vector representations of content), enabling semantic/similarity search via k-nearest-neighbor queries -- finding conceptually similar content rather than exact keyword matches, which is the basis for vector search in AI applications", "knn queries are a deprecated feature no longer supported in current Elasticsearch versions", "dense_vector fields replace the need for any other field type in a mapping"]', 1, 'Vector search via dense_vector/knn is what enables Elasticsearch to support semantic search use cases (like RAG systems) beyond traditional keyword-based full-text search.', 'intermediate'),

-- ---------- databases/elasticsearch/fundamentals ----------
('databases', 'elasticsearch', 'fundamentals', 'What is the practical difference between a text field and a keyword field in an Elasticsearch mapping?', '["They are functionally identical, differing only in internal storage format", "A text field is tokenized/analyzed for full-text search but cannot be used for aggregations or sorting directly; a keyword field is stored as an exact, unanalyzed value, supporting exact match, aggregations, and sorting but not full-text search -- this is why the multi-field pattern (mapping the same field as both) is the most common production setup", "keyword fields support full-text search, while text fields only support exact matching", "Only text fields can be used in a bool query at all"]', 1, 'This text vs. keyword distinction is described as one of the very first concepts that trips up almost everyone coming from a relational-database background, precisely because it has no direct single-type equivalent there.', 'beginner'),
('databases', 'elasticsearch', 'fundamentals', 'In a bool query, what is the functional difference between placing a condition in `must` versus `filter`?', '["must and filter produce identical results with no practical difference", "must clauses contribute to the relevance score and are required to match; filter clauses are also required (AND logic) but do NOT contribute to the score, and filter results are cached -- exact-match/range conditions that shouldn''t affect ranking (like a category or price range) belong in filter, not must", "filter clauses are optional (OR logic), unlike must clauses", "Only must clauses can be combined with should clauses in the same query"]', 1, 'Choosing filter over must for non-relevance-affecting conditions is both a correctness matter (avoiding unintended score contribution) and a performance one (filter results are cached).', 'intermediate'),
('databases', 'elasticsearch', 'fundamentals', 'Why does a match query on a text field sometimes fail to behave like a SQL LIKE \'%...%\' substring search?', '["match queries are identical to substring search in every case", "A match query on a text field is analyzed -- it tokenizes both the query and indexed text (lowercasing, splitting on word boundaries, possibly stemming) and matches based on resulting tokens, not the literal substring -- for genuine substring matching, options include wildcard queries, an ngram analyzer, or a keyword field with regexp", "match queries only work on numeric fields, never text", "Substring search is impossible in Elasticsearch under any configuration"]', 1, 'This is a very common point of confusion for anyone assuming match behaves like a simple string-contains check -- understanding tokenization is what explains the actual, sometimes-surprising matching behavior.', 'intermediate'),
('databases', 'elasticsearch', 'fundamentals', 'Why does elasticsearch-py client code using `es.search(index="products", body={"query": {...}})` represent outdated syntax in current versions?', '["This syntax has always been invalid Python and would raise an error immediately", "elasticsearch-py v8.0+ deprecated the body= parameter for all APIs in favor of top-level keyword arguments -- the current pattern is es.search(index=\"products\", query={\"match\": {...}}) -- a lot of older tutorials and examples still show the deprecated body= pattern", "body= is still the only valid way to pass a query, and the alternative shown is invalid", "This deprecation only affects the search() method, not other client methods"]', 1, 'Recognizing this specific, real client-library deprecation (not just theoretical) is genuinely useful for correctly reading and writing current elasticsearch-py code rather than following outdated tutorials.', 'intermediate'),
('databases', 'elasticsearch', 'fundamentals', 'What does `"size": 0` accomplish in an aggregation query, and why is it commonly used?', '["It deletes all documents matching the query", "It suppresses returning the actual matched documents in the response, returning only the aggregation results -- useful when only summary statistics (like counts or averages) are needed, avoiding the overhead of also fetching and transferring individual matching documents", "size: 0 disables the query entirely, returning no results of any kind including aggregations", "This setting only works when combined with a match_all query"]', 1, 'This is a common, practical pattern for dashboard-style summary queries where the individual matching documents are irrelevant and only the aggregated statistics matter.', 'beginner'),

-- ---------- databases/elasticsearch/intermediate ----------
('databases', 'elasticsearch', 'intermediate', 'What does field_value_factor with a "log1p" modifier accomplish in a function_score query?', '["It excludes documents below a certain rating from the results entirely", "It boosts a document''s relevance score based on a numeric field value (like rating), with the log1p modifier applying a logarithmic dampening so the boost effect diminishes at higher values rather than scaling linearly -- useful for incorporating a signal like rating without letting it completely dominate the base relevance score", "log1p converts the field from a number to a string before scoring", "This function can only be used with the keyword field type"]', 1, 'The logarithmic dampening specifically prevents a numeric boosting signal from overwhelming the underlying text-relevance score at high values -- a real, deliberate scoring design choice.', 'advanced'),
('databases', 'elasticsearch', 'intermediate', 'What problem does the percolator (registering a query as a document, then checking which registered queries match a new document) solve?', '["It speeds up standard full-text search queries", "It inverts the normal search direction -- instead of finding documents matching a query, it finds which of many stored queries match a newly-arrived document, which is the mechanism behind use cases like \"alert me when a new product matching these criteria is added\"", "Percolator is used exclusively for spelling correction", "Percolator queries can only be run once per index and then are permanently disabled"]', 1, 'This reverse-search pattern is specifically useful for alerting/notification systems where many users have different saved criteria and need to be notified when new matching content appears.', 'advanced'),
('databases', 'elasticsearch', 'intermediate', 'Why is `multi_match` with field boosts like `"name^3"` combined with `fuzziness: "AUTO"` a common relevance-tuning pattern?', '["fuzziness AUTO disables all typo tolerance, making matching stricter", "Field boosts weight certain fields (like name) as more important to the relevance score than others (like description), while fuzziness AUTO provides automatic typo tolerance scaled to term length -- combined, this lets a search be both weighted toward the most relevant fields and forgiving of minor spelling mistakes", "multi_match can only search a single field at a time, making boosts meaningless", "This combination is deprecated in favor of a single unified scoring algorithm"]', 1, 'Combining field-importance weighting with typo tolerance is a genuinely common real-world relevance-tuning pattern for product/content search, addressing two different aspects of match quality at once.', 'intermediate'),
('databases', 'elasticsearch', 'intermediate', 'What real operational risk does relying entirely on dynamic mapping for data with unpredictable field names create?', '["Dynamic mapping has no real risk and is always the safer choice", "Each previously-unseen field name becomes a permanent addition to the index''s mapping (mappings don''t shrink back down) -- if field names themselves are unpredictable (e.g. arbitrary webhook payload keys), this can cause the mapping to balloon to tens of thousands of fields, degrading performance and eventually causing indexing to fail once the field-count limit is hit", "Dynamic mapping only affects query speed, never indexing", "This risk only applies to numeric fields, not string fields"]', 1, 'This \"mapping explosion\" failure mode is a real, reproducible production risk specifically when field names (not just values) are unpredictable -- explicit mapping or the flattened field type is the standard mitigation.', 'advanced'),
('databases', 'elasticsearch', 'intermediate', 'Why does Redis Streams-style durable messaging have a rough conceptual parallel worth drawing to Elasticsearch''s own durability-related caveats around dynamic mapping and index design?', '["There is no meaningful parallel between these two unrelated technologies", "Both illustrate a broader pattern: a convenient default behavior (Pub/Sub''s fire-and-forget delivery, or Elasticsearch''s dynamic mapping) works well within its intended scope but creates real problems when applied beyond that scope (data requiring guaranteed delivery, or field names that are genuinely unpredictable) -- recognizing when a convenient default has outgrown its safe use case is a transferable database-design skill", "Elasticsearch and Redis use identical underlying storage engines", "This comparison is only relevant for candidates studying both technologies simultaneously"]', 1, 'This is a deliberately cross-technology conceptual question -- the specific mechanisms differ, but the underlying pattern (a convenient default with a real boundary condition) is a genuinely transferable way to reason about database defaults generally.', 'advanced'),

-- ---------- databases/elasticsearch/advanced ----------
('databases', 'elasticsearch', 'advanced', 'What is the actual reason JVM heap size recommendations for Elasticsearch cap around 30-31GB, even on servers with much more RAM available?', '["Elasticsearch has a hard-coded software limit preventing larger heaps", "This relates to \"compressed ordinary object pointers\" (compressed oops), a JVM feature that uses 32-bit references instead of 64-bit ones for heaps under roughly 32GB, reducing memory overhead per object -- crossing that threshold switches to full 64-bit pointers, which can make actual memory efficiency paradoxically worse despite the larger nominal heap", "Larger heaps are technically supported but void the Elastic support contract", "This limit only applies to Elasticsearch running in Docker containers"]', 1, 'Understanding the JVM mechanism behind this recommendation (not just memorizing \"cap around 30GB\") is what lets someone correctly apply it -- e.g. recognizing that a 128GB server should still use ~30GB heap, not 64GB.', 'advanced'),
('databases', 'elasticsearch', 'advanced', 'Why does the standard recommendation call for exactly 3 dedicated master-eligible nodes rather than 2 or 4 in a production cluster?', '["Master elections in Elasticsearch don''t require any voting or quorum mechanism", "Master elections require a majority (quorum) vote to avoid split-brain scenarios -- with 3 nodes, quorum is 2, meaning the cluster can survive losing any single node and still elect a new master; with only 2, losing either halts election entirely, and an even number like 4 doesn''t meaningfully improve resilience over 3 while adding cost", "4 master nodes is actually the standard recommendation, not 3", "Master node count has no relationship to split-brain prevention"]', 1, 'This quorum-based reasoning is the same general principle that shows up in other distributed systems (Redis Sentinel, for instance) -- odd numbers avoid the split-vote problem that even numbers can create.', 'advanced'),
('databases', 'elasticsearch', 'advanced', 'Why might running `_forcemerge` during peak production traffic make search performance temporarily worse before it gets better?', '["_forcemerge only ever runs during scheduled maintenance windows and cannot be triggered manually", "_forcemerge is a genuinely resource-intensive operation that rewrites segments, consolidating many smaller ones into fewer larger ones -- this consumes significant CPU and I/O while running, which can noticeably degrade concurrent search performance for the duration, even though the end result (fewer, more efficient segments) is an improvement", "_forcemerge has no measurable performance impact under any circumstances", "This operation only affects indexing speed, never search query performance"]', 1, 'This is exactly why standard practice is to run _forcemerge during low-traffic windows, ideally on indices no longer being actively written to, rather than on a hot, actively-queried index.', 'advanced'),
('databases', 'elasticsearch', 'advanced', 'Why is measuring search relevance quality with an actual metric (click-through rate, a scored relevance judgment set) considered essential rather than optional for iterative relevance tuning?', '["Individual complaint reports always provide sufficient signal on their own", "Relevance tuning changes interact with each other in ways not visible from any single query in isolation -- a change that fixes one reported bad result can simultaneously degrade many other, unreported queries, and without measuring aggregate quality, there''s no way to know whether a series of individually-reasonable changes has a net positive or negative overall effect", "Relevance quality cannot be measured quantitatively under any methodology", "This concern only applies to Elasticsearch, not other search engines"]', 1, 'This is a genuinely important process discipline for relevance tuning specifically -- complaint-driven, unmeasured tuning can make average search quality worse even while every individually-reported issue appears \"fixed.\"', 'advanced'),
('databases', 'elasticsearch', 'advanced', 'Why does a red cluster status NOT automatically mean permanent, unrecoverable data loss has occurred?', '["Red status is purely cosmetic and never indicates a real problem", "Red indicates at least one primary shard is currently unassigned, which is serious, but if a replica of that shard exists elsewhere in the cluster, promoting that replica to primary can resolve it without actual data loss -- genuine unrecoverable loss specifically requires that no reachable replica exists anywhere for the affected shard", "Red status always means the entire cluster''s data is permanently gone", "Replicas cannot be promoted to primary under any circumstances, making red always catastrophic"]', 1, 'This distinction is exactly why running with zero replicas (some single-node or cost-minimized setups) turns any single node failure into genuine, unrecoverable data loss -- replicas are what make a red status often recoverable rather than catastrophic.', 'advanced');
